-- The in-game leaderboard choice is one choice for the whole WoW account (one addon = one producer). Until now it
-- reached only the characters logged in after the choice. This applies the newest choice of every addon to all its
-- characters whose own last choice is older; a later choice made on the website for one character still wins.
-- Data only, safe to run again (lib/publish.ts applyAccountChoice does the same after every upload).
UPDATE atlas_profiles SET
  "public"=CASE (SELECT json_extract(o.payload,'$.public') FROM atlas_observations o JOIN atlas_grants g ON g.id=o.grant_id AND g.user_id=o.user_id AND g.producer_id=o.producer_id WHERE o.user_id=atlas_profiles.user_id AND o.producer_id=atlas_profiles.producer_id AND o.kind='character.publish' AND g.revoked_at IS NULL AND EXISTS(SELECT 1 FROM json_each(g.scopes) WHERE value='own_character') ORDER BY MIN(o.observed_at,COALESCE(CAST(json_extract(o.payload,'$.chosenAt') AS INTEGER),o.observed_at)) DESC,o.observed_at DESC,o.rowid DESC LIMIT 1) WHEN 1 THEN 1 ELSE 0 END,
  show_item_level=COALESCE((SELECT json_extract(o.payload,'$.showItemLevel') FROM atlas_observations o JOIN atlas_grants g ON g.id=o.grant_id AND g.user_id=o.user_id AND g.producer_id=o.producer_id WHERE o.user_id=atlas_profiles.user_id AND o.producer_id=atlas_profiles.producer_id AND o.kind='character.publish' AND g.revoked_at IS NULL AND EXISTS(SELECT 1 FROM json_each(g.scopes) WHERE value='own_character') ORDER BY MIN(o.observed_at,COALESCE(CAST(json_extract(o.payload,'$.chosenAt') AS INTEGER),o.observed_at)) DESC,o.observed_at DESC,o.rowid DESC LIMIT 1),show_item_level),
  show_guild=COALESCE((SELECT json_extract(o.payload,'$.showGuild') FROM atlas_observations o JOIN atlas_grants g ON g.id=o.grant_id AND g.user_id=o.user_id AND g.producer_id=o.producer_id WHERE o.user_id=atlas_profiles.user_id AND o.producer_id=atlas_profiles.producer_id AND o.kind='character.publish' AND g.revoked_at IS NULL AND EXISTS(SELECT 1 FROM json_each(g.scopes) WHERE value='own_character') ORDER BY MIN(o.observed_at,COALESCE(CAST(json_extract(o.payload,'$.chosenAt') AS INTEGER),o.observed_at)) DESC,o.observed_at DESC,o.rowid DESC LIMIT 1),show_guild),
  show_gear=COALESCE((SELECT json_extract(o.payload,'$.showGear') FROM atlas_observations o JOIN atlas_grants g ON g.id=o.grant_id AND g.user_id=o.user_id AND g.producer_id=o.producer_id WHERE o.user_id=atlas_profiles.user_id AND o.producer_id=atlas_profiles.producer_id AND o.kind='character.publish' AND g.revoked_at IS NULL AND EXISTS(SELECT 1 FROM json_each(g.scopes) WHERE value='own_character') ORDER BY MIN(o.observed_at,COALESCE(CAST(json_extract(o.payload,'$.chosenAt') AS INTEGER),o.observed_at)) DESC,o.observed_at DESC,o.rowid DESC LIMIT 1),show_gear),
  visibility_at=(SELECT MIN(o.observed_at,COALESCE(CAST(json_extract(o.payload,'$.chosenAt') AS INTEGER),o.observed_at)) FROM atlas_observations o JOIN atlas_grants g ON g.id=o.grant_id AND g.user_id=o.user_id AND g.producer_id=o.producer_id WHERE o.user_id=atlas_profiles.user_id AND o.producer_id=atlas_profiles.producer_id AND o.kind='character.publish' AND g.revoked_at IS NULL AND EXISTS(SELECT 1 FROM json_each(g.scopes) WHERE value='own_character') ORDER BY MIN(o.observed_at,COALESCE(CAST(json_extract(o.payload,'$.chosenAt') AS INTEGER),o.observed_at)) DESC,o.observed_at DESC,o.rowid DESC LIMIT 1)
WHERE (SELECT MIN(o.observed_at,COALESCE(CAST(json_extract(o.payload,'$.chosenAt') AS INTEGER),o.observed_at)) FROM atlas_observations o JOIN atlas_grants g ON g.id=o.grant_id AND g.user_id=o.user_id AND g.producer_id=o.producer_id WHERE o.user_id=atlas_profiles.user_id AND o.producer_id=atlas_profiles.producer_id AND o.kind='character.publish' AND g.revoked_at IS NULL AND EXISTS(SELECT 1 FROM json_each(g.scopes) WHERE value='own_character') ORDER BY MIN(o.observed_at,COALESCE(CAST(json_extract(o.payload,'$.chosenAt') AS INTEGER),o.observed_at)) DESC,o.observed_at DESC,o.rowid DESC LIMIT 1) IS NOT NULL
  AND (SELECT json_extract(o.payload,'$.public') FROM atlas_observations o JOIN atlas_grants g ON g.id=o.grant_id AND g.user_id=o.user_id AND g.producer_id=o.producer_id WHERE o.user_id=atlas_profiles.user_id AND o.producer_id=atlas_profiles.producer_id AND o.kind='character.publish' AND g.revoked_at IS NULL AND EXISTS(SELECT 1 FROM json_each(g.scopes) WHERE value='own_character') ORDER BY MIN(o.observed_at,COALESCE(CAST(json_extract(o.payload,'$.chosenAt') AS INTEGER),o.observed_at)) DESC,o.observed_at DESC,o.rowid DESC LIMIT 1) IS NOT NULL
  AND COALESCE(visibility_at,0)<(SELECT MIN(o.observed_at,COALESCE(CAST(json_extract(o.payload,'$.chosenAt') AS INTEGER),o.observed_at)) FROM atlas_observations o JOIN atlas_grants g ON g.id=o.grant_id AND g.user_id=o.user_id AND g.producer_id=o.producer_id WHERE o.user_id=atlas_profiles.user_id AND o.producer_id=atlas_profiles.producer_id AND o.kind='character.publish' AND g.revoked_at IS NULL AND EXISTS(SELECT 1 FROM json_each(g.scopes) WHERE value='own_character') ORDER BY MIN(o.observed_at,COALESCE(CAST(json_extract(o.payload,'$.chosenAt') AS INTEGER),o.observed_at)) DESC,o.observed_at DESC,o.rowid DESC LIMIT 1);
